#!/bin/sh
# @TITLE@ (Unity) - local / CI check. Every gate that exists today and, when a Unity editor is present
# (UNITY_EDITOR=/path/to/Unity), the EditMode tests in batch mode.
#   sh games/@SLUG@/unity/Tools/check.sh
# Generated by games/tools/unity/new_game.sh (U0). P1..P7 add their gates here (sim + balance runner, strings, IAP,
# store listing, icons, fonts - Volt City's unity/Tools/check.sh is the full model).
set -eu
HERE=$(cd "$(dirname "$0")" && pwd)
UNITY=$(dirname "$HERE")
FAIL=0
step() { printf '\n== %s\n' "$1"; }
have_dotnet() { [ -n "${DOTNET:-}" ] || command -v dotnet >/dev/null 2>&1 || [ -x /Volumes/BuildSSD/game-deps/dotnet-sdk/dotnet ] || [ -x /Volumes/BuildSSD/tmp/dotnet-sdk/dotnet ]; }

step "source gates (G1-G8, incl. kit drift against games/tools/unity)"
python3 "$HERE/check_unity_sources.py" || FAIL=1

step "IP denylist (+ proof, nobody is hurt)"
python3 "$HERE/ip_denylist.py" || FAIL=1

step "engine-free CoddyKit.Core + kit tests (dotnet)"
if have_dotnet; then
    OUT=$(sh "$HERE/dotnet_check.sh" 2>&1) || FAIL=1
    echo "$OUT" | tail -3
    echo "$OUT" | grep -q "Passed!" || FAIL=1
else
    echo "SKIP: no .NET SDK (set DOTNET=) - the Unity EditMode run below covers the same tests"
fi

step "C# 9 syntax of every script (Roslyn parse, 2 define sets)"
if have_dotnet; then
    sh "$HERE/cs_parse_check.sh" | tail -1 || FAIL=1
else
    echo "SKIP: no .NET SDK"
fi

step "Unity EditMode tests"
if [ -n "${UNITY_EDITOR:-}" ] && [ -x "$UNITY_EDITOR" ]; then
    mkdir -p "$UNITY/Build"
    # alarm: an editor that hangs on import must not block the agent forever
    ( "$UNITY_EDITOR" -batchmode -nographics -projectPath "$UNITY" -runTests -testPlatform EditMode \
        -testResults "$UNITY/Build/editmode.xml" -logFile "$UNITY/Build/editmode.log" ) &
    PID=$!
    # alarm output to /dev/null: a caller piping check.sh must not wait for the alarm's open pipe
    ( sleep "${UNITY_TEST_TIMEOUT_S:-1800}" && kill "$PID" 2>/dev/null ) >/dev/null 2>&1 &
    WATCH=$!
    if wait "$PID"; then
        echo "EDITMODE: pass $(grep -o 'total="[0-9]*" passed="[0-9]*" failed="[0-9]*"' "$UNITY/Build/editmode.xml" | head -1) ($UNITY/Build/editmode.xml)"
    else echo "EDITMODE: FAIL (see Build/editmode.log)"; FAIL=1; fi
    kill "$WATCH" 2>/dev/null || true
    pkill -P "$WATCH" sleep 2>/dev/null || true
else
    echo "SKIP: UNITY_EDITOR not set (Mini: /Volumes/BuildSSD/unity/editors/6000.3.27f1/Unity.app/Contents/MacOS/Unity)"
fi

[ "$FAIL" -eq 0 ] && printf '\n@PREFIX@_UNITY_CHECK: PASS\n' || printf '\n@PREFIX@_UNITY_CHECK: FAIL\n'
exit "$FAIL"
